<?php

declare(strict_types=1);
namespace CajeerEngine\ImportExport;

use CajeerEngine\Update\OperationFiles as F;

/** Portable data only. Archive member names are generated by the engine, never by input paths. */
final class SitePackage
{
    public const FORMAT = 'cajeerengine.export.v3';
    private const META_LIMIT = 32 * 1024 * 1024;
    private const FILE_LIMIT = 100 * 1024 * 1024;
    public const TOTAL_LIMIT = 4 * 1024 * 1024 * 1024;
    private const COUNT_LIMIT = 20000;
    public readonly string $dir;
    public array $manifest = [];
    public array $data = [];
    public array $files = [];
    public string $digest = '';
    private int $mediaBytes = 0;

    public function __construct(string $root)
    {
        $base = F::path($root, 'storage/app/import-staging');
        F::dir($base, 02770);
        $this->dir = $base . '/' . bin2hex(random_bytes(16));
        F::dir($this->dir, 0700);
    }

    public static function encode(mixed $v): string
    {
        return json_encode($v, JSON_THROW_ON_ERROR | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    }

    public function addMedia(string $source, string $checksum): void
    {
        if (!preg_match('/^[a-f0-9]{64}$/D', $checksum)) throw new \InvalidArgumentException('Invalid media checksum');
        if (isset($this->files[$checksum])) return;
        $size = filesize($source);
        if ($size === false || $size < 1 || $size > self::FILE_LIMIT || count($this->files) >= self::COUNT_LIMIT || $this->mediaBytes + $size > self::TOTAL_LIMIT) throw new \RuntimeException('Media package limit exceeded');
        $dest = $this->dir . '/' . $checksum;
        F::copy($source, $dest);
        if (!hash_equals($checksum, F::hash($dest))) throw new \RuntimeException('Media checksum mismatch');
        $this->files[$checksum] = $dest;
        $this->mediaBytes += $size;
    }

    public function write(string $path, array $data, string $version, bool $legacy): array
    {
        $manifest = ['format'=>$legacy?'cajeerengine.export.v2':self::FORMAT,'version'=>$version,'created_at'=>gmdate(DATE_ATOM),'sections'=>array_keys($data)];
        if ($legacy) {
            if (isset($data['media'])) {
                $data['media']['files'] = [];
                $total = 0;
                foreach ($this->files as $hash=>$file) {
                    $total += filesize($file);
                    if ($total > 16*1024*1024) throw new \RuntimeException('Use ZIP for large media exports');
                    $data['media']['files'][]=['checksum'=>$hash,'content_base64'=>base64_encode((string)file_get_contents($file))];
                }
            }
            $manifest['checksum']=hash('sha256',self::encode($data));
            $manifest['media_files_embedded']=!empty($this->files);
            $json=self::encode(['manifest'=>$manifest,'data'=>$data]);
            if(strlen($json)>self::META_LIMIT) throw new \RuntimeException('Legacy JSON export too large');
            F::write($path,$json,0640); return $manifest;
        }
        $members=[]; $total=0; $metadata=0;
        foreach ($data as $section=>$value) {
            $name='data/'.$section.'.json';
            $json=self::encode($value);
            $metadata+=strlen($json);
            if(strlen($json)>self::META_LIMIT||$metadata>64*1024*1024) throw new \RuntimeException('Section metadata limit exceeded: '.$section);
            $p=$this->dir.'/'.$section.'.json'; F::write($p,$json); $members[$name]=$p;
        }
        foreach($this->files as $hash=>$file) $members['media/'.$hash]=$file;
        foreach($members as $name=>$file) {
            $size=filesize($file); $total+=$size;
            $manifest['files'][$name]=['size'=>$size,'sha256'=>F::hash($file)];
        }
        if($total>self::TOTAL_LIMIT) throw new \RuntimeException('Package exceeds total limit');
        $manifest['files']??=[];
        $manifestPath=$this->dir.'/manifest.json'; F::write($manifestPath,self::encode($manifest));
        $temp=$this->dir.'/package.zip';
        if(class_exists(\ZipArchive::class)) {
            $zip=new \ZipArchive(); if($zip->open($temp,\ZipArchive::CREATE|\ZipArchive::EXCL)!==true)throw new \RuntimeException('Cannot create ZIP');
            foreach($members+['manifest.json'=>$manifestPath] as $name=>$file) if(!$zip->addFile($file,$name)||!$zip->setExternalAttributesName($name,\ZipArchive::OPSYS_UNIX,0100600<<16))throw new \RuntimeException('Cannot write ZIP member');
            if(!$zip->close())throw new \RuntimeException('Cannot finalize ZIP');
        } else {
            $zip=new \PharData($temp,0,null,\Phar::ZIP); foreach($members+['manifest.json'=>$manifestPath] as $name=>$file) $zip->addFile($file,$name); unset($zip);
        }
        F::copy($temp,$path,0640); return $manifest;
    }

    public function read(string $source): void
    {
        if(is_link($source)||!is_file($source)||filesize($source)>self::TOTAL_LIMIT) throw new \InvalidArgumentException('Invalid or oversized package');
        $ext=strtolower(pathinfo($source,PATHINFO_EXTENSION));
        if(!in_array($ext,['json','zip'],true))throw new \InvalidArgumentException('Expected ZIP or JSON package');
        if($ext==='json'&&filesize($source)>self::META_LIMIT)throw new \InvalidArgumentException('Legacy JSON too large');
        $copy=$this->dir.'/input.'.$ext; F::copy($source,$copy); $this->digest=F::hash($copy);
        if($ext==='json') {
            $p=F::read($copy); $this->manifest=$p['manifest']??[]; $this->data=$p['data']??[];
            if(($this->manifest['format']??null)!=='cajeerengine.export.v2'||!is_array($this->data)||!hash_equals((string)($this->manifest['checksum']??''),hash('sha256',self::encode($this->data))))throw new \InvalidArgumentException('Invalid legacy v2 checksum or format');
            foreach($this->data['media']['files']??[] as $file) {
                $hash=$file['checksum']??''; $bytes=base64_decode((string)($file['content_base64']??''),true);
                if(!is_string($bytes)||!is_string($hash)||!hash_equals($hash,hash('sha256',$bytes)))throw new \InvalidArgumentException('Invalid legacy media');
                if(isset($this->files[$hash]))continue;
                $p=$this->dir.'/'.$hash; F::write($p,$bytes); $this->files[$hash]=$p;
            }
            unset($this->data['media']['files']); return;
        }
        $this->readZip($copy);
    }

    private function readZip(string $path): void
    {
        $names=[]; $raw=null;
        if(class_exists(\ZipArchive::class)) {
            $raw=new \ZipArchive(); if($raw->open($path,\ZipArchive::CHECKCONS)!==true)throw new \InvalidArgumentException('Invalid ZIP');
            if($raw->numFiles>self::COUNT_LIMIT+10)throw new \InvalidArgumentException('Too many ZIP members');
            for($i=0;$i<$raw->numFiles;$i++) {
                $name=$raw->getNameIndex($i); if(!is_string($name)||isset($names[$name]))throw new \InvalidArgumentException('Duplicate ZIP member');
                if($raw->getExternalAttributesIndex($i,$os,$attr)&&$os===3&&!in_array(($attr>>16)&0170000,[0,0100000],true))throw new \InvalidArgumentException('Nonregular ZIP member');
                $names[$name]=true;
            }
            $raw->close();
        } else {
            // Phar hides duplicate names. Verify the raw directory with Info-ZIP before using streams.
            $names=$this->rawNames($path);
        }
        foreach($names as $name=>$_) if(!preg_match('~^(manifest\.json|data/[a-z_]+\.json|media/[a-f0-9]{64})$~D',$name))throw new \InvalidArgumentException('Forbidden ZIP member');
        $zip=new \PharData($path);
        if(!isset($names['manifest.json'])||$zip['manifest.json']->getSize()>self::META_LIMIT)throw new \InvalidArgumentException('Missing or oversized package manifest');
        $this->manifest=json_decode($zip['manifest.json']->getContent(),true,64,JSON_THROW_ON_ERROR);
        $inventory=$this->manifest['files']??null;
        if(($this->manifest['format']??null)!==self::FORMAT||!is_array($inventory)||count($inventory)!==count($names)-1)throw new \InvalidArgumentException('Invalid package inventory');
        unset($names['manifest.json']); $total=0; $metadata=0;
        foreach($inventory as $name=>$info) {
            if(!isset($names[$name])||!is_array($info)||!is_int($info['size']??null)||!is_string($info['sha256']??null)||!preg_match('/^[a-f0-9]{64}$/D',$info['sha256']))throw new \InvalidArgumentException('Invalid member inventory');
            $isMedia=str_starts_with($name,'media/'); $size=$zip[$name]->getSize(); $total+=$size;if(!$isMedia)$metadata+=$size;
            if($metadata>64*1024*1024||$size!==$info['size']||$size<0||$size>($isMedia?self::FILE_LIMIT:self::META_LIMIT)||$total>self::TOTAL_LIMIT)throw new \InvalidArgumentException('ZIP size limit or mismatch');
            $dest=$this->dir.'/member-'.hash('sha256',$name); $in=fopen('phar://'.$path.'/'.$name,'rb'); $out=fopen($dest,'xb');
            try { if(!$in||!$out||stream_copy_to_stream($in,$out,$size+1)!==$size)throw new \RuntimeException('ZIP member read failed'); }
            finally {if(is_resource($in))fclose($in);if(is_resource($out))fclose($out);}
            if(!hash_equals($info['sha256'],F::hash($dest)))throw new \InvalidArgumentException('ZIP member checksum mismatch');
            if($isMedia) { $hash=substr($name,6); if($hash!==$info['sha256'])throw new \InvalidArgumentException('Invalid media identity'); $this->files[$hash]=$dest; }
            else { $section=substr($name,5,-5); $this->data[$section]=F::read($dest); }
            unset($names[$name]);
        }
        if($names!==[]||!is_array($this->manifest['sections']??null)||!array_is_list($this->manifest['sections'])||count(array_unique($this->manifest['sections'],SORT_REGULAR))!==count($this->manifest['sections'])||array_diff($this->manifest['sections'],['content','media','cms','settings'])||array_diff(array_keys($this->data),$this->manifest['sections'])||array_diff($this->manifest['sections'],array_keys($this->data)))throw new \InvalidArgumentException('Package sections mismatch');
    }

    private function rawNames(string $path): array
    {
        $p=proc_open(['unzip','-Z1',$path],[1=>['pipe','w'],2=>['file','/dev/null','w']],$pipes);
        if(!is_resource($p))throw new \RuntimeException('Install ext-zip or unzip');
        $names=[]; $bad=false;
        while(($line=fgets($pipes[1],1024))!==false) { $name=rtrim($line,"\r\n"); if(!preg_match('~^(manifest\.json|data/[a-z_]+\.json|media/[a-f0-9]{64})$~D',$name)||isset($names[$name])||count($names)>self::COUNT_LIMIT+10){$bad=true;break;} $names[$name]=true; }
        fclose($pipes[1]); if($bad)proc_terminate($p); if(proc_close($p)!==0||$bad)throw new \InvalidArgumentException('Invalid ZIP member list');
        $p=proc_open(['unzip','-Z','-l',$path],[1=>['pipe','w'],2=>['file','/dev/null','w']],$pipes); if(!is_resource($p))throw new \RuntimeException('Cannot inspect ZIP');
        $bad=false;while(($line=fgets($pipes[1],1024))!==false)if(preg_match('/^[dlbcps][rwxStTs-]{9}\s/',$line))$bad=true;
        fclose($pipes[1]);if(proc_close($p)!==0||$bad)throw new \InvalidArgumentException('Nonregular ZIP member');return $names;
    }
    public function close(): void
    {
        foreach(new \DirectoryIterator($this->dir) as $item) if(!$item->isDot()) { if(!$item->isFile()||$item->isLink())throw new \RuntimeException('Unexpected staging file'); unlink($item->getPathname()); }
        rmdir($this->dir);
    }
}
